using System.Reflection;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Nodes;

namespace CombatSolver;

internal sealed partial class CombatRootSnapshot
{
    private static readonly (string Name, FieldInfo? Field)[] PotionInventoryEventFields =
        new[]
        {
            nameof(Player.MaxPotionCountChanged), nameof(Player.PotionProcured),
            nameof(Player.PotionDiscarded), nameof(Player.UsedPotionRemoved),
            nameof(Player.AddPotionFailed), nameof(Player.CanUseOrRemovePotionsChanged),
        }.Select(name => (name, typeof(Player).GetField(name,
            BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.DeclaredOnly))).ToArray();

    private static readonly FieldInfo? PotionBeforeUseField = typeof(PotionModel).GetField(
        nameof(PotionModel.BeforeUse),
        BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.DeclaredOnly);

    // Only absence is certified. Native UI receivers also remain unproven here;
    // their assembly or method name is not evidence that callbacks cannot refill.
    // Cache field metadata, never delegates or a result from another live root.
    private static string? CapturePotionInventoryEventRejection(Player player)
    {
        if (!NGame.IsMainThread())
            throw new InvalidOperationException("Potion inventory events must be captured on the main thread.");
        foreach (var (name, field) in PotionInventoryEventFields)
        {
            if (field is null || !typeof(Delegate).IsAssignableFrom(field.FieldType))
                return $"inventory_event_layout:Player.{name}";
            if (field.GetValue(player) is not null)
                return $"inventory_event:Player.{name}";
        }
        if (PotionBeforeUseField is null || !typeof(Delegate).IsAssignableFrom(PotionBeforeUseField.FieldType))
            return "inventory_event_layout:PotionModel.BeforeUse";
        for (int slot = 0; slot < player.PotionSlots.Count; slot++)
        {
            if (player.PotionSlots[slot] is { } potion && PotionBeforeUseField.GetValue(potion) is not null)
                return $"inventory_event:PotionModel.BeforeUse:{slot}";
        }
        return null;
    }
}

