                [new(0, "ENERGY_POTION", SolverPotionDirective.Force)]) },
        })
        {
            var guarded = new CombatBeamSolver(root, names, damage, guard,
                potionPolicyOverride: SolverPotionPolicy.RequireAtLeastOne,
                potionFreePolicyBaseline: baseline, minimumPotionUses: 2, maximumPotionUses: 2,
                directSearchPurpose: DirectSearchPurpose.SmartPotionGradient);
            if (guarded._smartPotionEligibilityHpCeiling is not null)
                throw new InvalidOperationException("Stock shortcut ignored existing policy/resource guard.");
        }
        return member._closedStockEligibilityBranchesPruned;
    }
}

