using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Potions;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private async Task AssertInventoryEventProofAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        await ClearPlayerPilesAsync(player);
        await InjectCardAsync(live, player, new() { CardId = "STRIKE_IRONCLAD", Pile = "Hand" });
        foreach (var potion in player.PotionSlots.ToArray()) potion?.Discard();
        InjectPotionForTest(player, "ENERGY_POTION");
        InjectPotionForTest(player, "SWIFT_POTION");
        SetEnergy(player, 3);
        CombatRootSnapshot baseline = CombatRootSnapshot.Capture(live);
        if (baseline.ClosedPotionInventory is null)
            throw new InvalidOperationException("Baseline inventory rejected: " + baseline.ComponentHealingRejection);
        PotionModel cheap = player.GetPotionAtSlotIndex(0)!;
        PotionModel expensive = player.GetPotionAtSlotIndex(1)!;
        int cheapCost = PotionUsePolicy.StrategicHpCost(cheap, false);
        int expensiveCost = PotionUsePolicy.StrategicHpCost(expensive, false);
        if (cheapCost != 9 || expensiveCost != 18)
            throw new InvalidOperationException($"Changed fixture costs: {cheapCost}/{expensiveCost}");
        int callbacks = 0;
        int refills = 0;
        void OnUsed(PotionModel potion)
        {
            callbacks++;
            if (refills != 0) return;
            if (!ReferenceEquals(potion, cheap))
                throw new InvalidOperationException("Unexpected first removed potion.");
            var replacement = (PotionModel)ModelDb.Potion<EnergyPotion>().MutableClone();
            if (!player.AddPotionInternal(replacement, 0).success)
                throw new InvalidOperationException("Public inventory callback refill failed.");
            refills++;
        }
        player.UsedPotionRemoved += OnUsed;
        try
        {
            CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
            if (root.ClosedPotionInventory is not { } stock)
                throw new InvalidOperationException("Counterexample refused at root: " + root.ComponentHealingRejection);
            var parent = root.ForkSimulator();
            var fork = parent.Fork();
            string parentBefore = DescribeContinuationContractState(parent, root, player);
            string forkBefore = DescribeContinuationContractState(fork, root, player);
            int? Cost(CombatPredictionSimulator sim) => stock.MinimumExplicitCost(sim, player, 2,
                StrategicHpRecoveryBound.ComponentHealingUpperBound(sim, player, 0));
            int floor = Cost(parent) ?? throw new InvalidOperationException("No frozen stock floor.");
            if (floor != cheapCost + expensiveCost || Cost(fork) != floor || callbacks != 0)
                throw new InvalidOperationException("Capture unexpectedly executed callback or stock costs changed.");
            using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(25));
            for (int i = 0; i < 2; i++)
            {
                var potion = player.GetPotionAtSlotIndex(0)!;
                GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                    queued => queued is UsePotionAction use && use.PotionIndex == 0
                        && ReferenceEquals(use.Player, player),
                    () => potion.EnqueueManualUse(player.Creature), deadline.Token);
                await action.CompletionTask.WaitAsync(deadline.Token);
                if (i == 0 && (refills != 1 || player.GetPotionAtSlotIndex(0)?.GetType() != typeof(EnergyPotion)))
                    throw new InvalidOperationException("First native use did not refill its slot.");
            }
            if (callbacks != 2 || refills != 1 || player.GetPotionAtSlotIndex(0) is not null
                || !ReferenceEquals(player.GetPotionAtSlotIndex(1), expensive)
                || 2 * cheapCost >= floor || Cost(parent) != floor || Cost(fork) != floor
                || DescribeContinuationContractState(parent, root, player) != parentBefore
                || DescribeContinuationContractState(fork, root, player) != forkBefore)
                throw new InvalidOperationException("Counterexample result or frozen parent/Fork isolation differed.");
            _completedChecks.Add($"InventoryEventProof:CurrentRootAcceptedUnknownUsedPotionRemoved:NativeUses=2:CallbackCalls={callbacks}:Refills={refills}:InitialCostFloor={floor}:ActualExplicitCost={2 * cheapCost}:ParentForkFullStateHistoryRngStable:NoCallbackDuringCapture:NoWrongPruneClaim");
        }
        finally { player.UsedPotionRemoved -= OnUsed; }
    }
}

